from datetime import datetime
from math import ceil


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("exit time cannot be earlier than entry time")

        duration_seconds = (exit - entry).total_seconds()
        duration_hours = duration_seconds / 3600.0

        # Stays of at most 15 minutes are free
        if duration_hours <= 0.25:
            return 0.0

        # Stays longer than 24 hours incur a flat penalty
        if duration_hours > 24.0:
            return 200.00

        # Every started hour is charged as a full hour
        billable_hours = ceil(duration_hours)
        return round(billable_hours * self.hourly_rate, 2)
